// Reproduction for: @ai-sdk/harness-claude-code reports a turn's CUMULATIVE
// usage as the LAST STEP's usage on any turn with two or more model calls,
// instead of that step's own usage.
//
// This runs the package's own bridge event-processing code (the exact
// shipped source at node_modules/@ai-sdk/harness-claude-code@1.0.78,
// imported by relative path so it's the real installed version, not a
// reimplementation) against a realistic two-step turn: one tool round trip
// (Bash), then a final text answer.
//
// What SHOULD happen: the `finish-step` emitted for the second (final) model
// call reports that call's own usage.
//
// What ACTUALLY happens: it reports the whole turn's cumulative usage
// (step 1 + step 2 summed) instead, per
// https://github.com/vercel/ai/blob/main/packages/harness-claude-code/src/bridge/index.ts#L424-L457
// — on `type === 'result'`, `harnessUsage` (mapped from the CLI's
// turn-ending, CUMULATIVE `usage`/`message.usage`) is passed to
// `emitFinishStep` in preference to `state.pendingStepUsage` (the final
// step's own usage, already sitting correctly in state from its own
// `assistant` message — see `create-emit-stream-event.ts`'s handling of
// `type === 'assistant'`, which is only ever closed out early by
// `closeStepIfReady()` when a tool call is pending; a text-only final
// response never calls it, so the step is still open when `result` arrives).
//
// Any consumer using `finish-step` usage to answer "how many tokens did the
// last model call use" (e.g. to show "how full is the context window right
// now") gets a wildly inflated number on every turn with 2+ model calls,
// subagents or not. This is a different bug from #18618 (subagent usage
// bleeding into the parent step), which is already fixed as of
// harness-claude-code@1.0.70 — this one is still present in the latest
// published version (1.0.78) at the time of writing.

import assert from "node:assert/strict";
// Deliberately a relative filesystem import, not the bare package specifier:
// the package's `exports` map only publishes the "." entry point, so this is
// the only way to run its *actual shipped source* (not a reimplementation)
// for a repository the CLI protocol internals aren't meant to be imported
// by. The source ships in the npm tarball (see the package's `files` field),
// pinned to the exact installed version — see package.json.
import {
  createClaudeStreamEventState,
  createEmitStreamEvent,
  emitFinishStep,
  mapUsage,
  type ClaudeMessage,
} from "./node_modules/@ai-sdk/harness-claude-code/src/bridge/create-emit-stream-event.ts";

type EmittedPart = Record<string, unknown>;

const emitted: EmittedPart[] = [];
const state = createClaudeStreamEventState();

const emitStreamEvent = createEmitStreamEvent({
  state,
  emit: (part) => emitted.push(part),
  emitWarning: () => {},
  emitTerminalError: (message) => {
    throw new Error(`unexpected terminal error: ${message}`);
  },
  onCompactionBoundary: () => {},
  toCommonName: (name) => name,
});

// --- The stream, exactly as the Claude Code CLI's `stream-json` output
// shapes it (field names/shape per create-emit-stream-event.ts's own
// `ClaudeMessage` type). Two model calls: a Bash tool round trip, then a
// final text-only answer.

const step1Usage = {
  input_tokens: 1000,
  cache_creation_input_tokens: 0,
  cache_read_input_tokens: 0,
  output_tokens: 50,
};
const step2OwnUsage = {
  input_tokens: 1800, // this call's own input, NOT cumulative
  cache_creation_input_tokens: 0,
  cache_read_input_tokens: 0,
  output_tokens: 70,
};
// The Claude Code CLI's turn-ending `result` usage is cumulative across the
// whole turn (confirmed in the #18618 report/fix: "the same number
// `finish.totalUsage` reports"). It is NOT step 2's own usage.
const cumulativeResultUsage = {
  input_tokens: step1Usage.input_tokens + step2OwnUsage.input_tokens, // 2800
  cache_creation_input_tokens: 0,
  cache_read_input_tokens: 0,
  output_tokens: step1Usage.output_tokens + step2OwnUsage.output_tokens, // 120
};

const stream: ClaudeMessage[] = [
  { type: "system", subtype: "init", model: "claude-sonnet-5" },
  {
    type: "assistant",
    message: {
      content: [
        {
          type: "tool_use",
          id: "toolu_01",
          name: "Bash",
          input: { command: "echo hi" },
        },
      ],
      usage: step1Usage,
    },
  },
  {
    type: "user",
    message: {
      content: [
        {
          type: "tool_result",
          tool_use_id: "toolu_01",
          content: "hi",
          is_error: false,
        },
      ],
    },
  },
  {
    type: "assistant",
    message: {
      content: [{ type: "text", text: "Done!" }],
      usage: step2OwnUsage,
    },
  },
  {
    type: "result",
    subtype: "success",
    result: "Done!",
    usage: cumulativeResultUsage,
  },
];

for (const msg of stream) {
  emitStreamEvent(msg);
}

// The `result` message's handling lives in bridge/index.ts, not in
// create-emit-stream-event.ts (see the citation above). Reproduced here
// verbatim from the published source, not reinterpreted:
//
//   const usage = msg.usage ?? msg.message?.usage;
//   const harnessUsage = mapUsage(usage);
//   if (harnessUsage) turnUsage = harnessUsage;
//   ...
//   if (streamEventState.stepOpen) {
//     emitFinishStep({
//       state: streamEventState,
//       emit,
//       usage: harnessUsage ?? streamEventState.pendingStepUsage,
//     });
//   }
const resultMsg = stream[stream.length - 1]!;
const harnessUsage = mapUsage(resultMsg.usage);
assert.ok(state.stepOpen, "expected the final text-only step to still be open when `result` arrives — this is the precondition for the bug");
if (state.stepOpen) {
  emitFinishStep({ state, emit: (part) => emitted.push(part), usage: harnessUsage ?? state.pendingStepUsage });
}

const finishSteps = emitted.filter((p) => p.type === "finish-step");
assert.equal(finishSteps.length, 2, `expected 2 finish-step parts, got ${finishSteps.length}`);

const [step1Emitted, step2Emitted] = finishSteps as [EmittedPart, EmittedPart];

console.log("finish-step #1 (tool-use step) usage:", JSON.stringify(step1Emitted.usage));
console.log("finish-step #2 (final text step) usage:", JSON.stringify(step2Emitted.usage));

const expectedStep2 = mapUsage(step2OwnUsage);
const actualStep2 = step2Emitted.usage;

console.log("\nExpected finish-step #2 usage (step 2's own call):", JSON.stringify(expectedStep2));
console.log("Actual finish-step #2 usage (bug: whole-turn cumulative):", JSON.stringify(actualStep2));

try {
  assert.deepEqual(actualStep2, expectedStep2);
  console.log("\nPASS — finish-step #2 reported its own usage. Bug not present.");
  process.exit(0);
} catch {
  console.log(
    "\nFAIL (bug reproduced) — finish-step #2 reported the whole turn's cumulative usage " +
      "(step 1 + step 2) instead of its own. A consumer tracking \"how many tokens did the " +
      "last model call use\" from finish-step will overcount by the entirety of every prior " +
      "step in the turn.",
  );
  process.exit(1);
}

